namespace SublimaLab.Application.Abstractions;

/// <summary>
/// Binary storage for uploaded files. Keys are generated by the storage implementation and
/// never derived from user input. Swap the local implementation for blob storage in production.
/// </summary>
public interface IFileStorage
{
    /// <param name="extension">Server-determined extension including the dot, e.g. ".png".</param>
    Task<string> SaveAsync(Stream content, string extension, CancellationToken cancellationToken);

    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken);

    Task DeleteAsync(string key, CancellationToken cancellationToken);
}
